import{Client}from"./ext/gr.min.js";import{CONFIG}from"./config.min.js";import{LimitedCache,getFileHash,compressImage}from"./utils.min.js";let client=null;const cache=new LimitedCache(CONFIG.CACHE_MAX_SIZE),pendingRequests=new Map;async function initializeClient(){try{client=await Client.connect(CONFIG.GRADIO_APP),console.log("FLOOFS READY TO PLAY")}catch(e){throw console.error("FLOOFS BUSY RN, SHOO:",e),e}}async function classifyImage(e){if(!client)throw new Error("API client not initialized");const t=await getFileHash(e);if(cache.has(t))return cache.get(t);if(pendingRequests.has(t))return console.log("Deduplicating request for:",e.name),await pendingRequests.get(t);const i=(async()=>{const i=document.querySelector("header");i?.classList.add("siren-effect");try{const i=await compressImage(e),n=await client.predict("/predict",{img:i});return cache.set(t,n.data),n.data}catch(e){throw console.error("Error classifying image:",e),new Error("Failed to classify image. Please try again.")}finally{i?.classList.remove("siren-effect")}})();pendingRequests.set(t,i);try{return await i}finally{pendingRequests.delete(t)}}function getCache(){return cache}function clearPendingRequests(){pendingRequests.clear()}export{initializeClient,classifyImage,getCache,clearPendingRequests};